-        if (aliasDefinition.getParent().isVar() &&
-            aliasDefinition.getParent().hasOneChild()) {
-          aliasDefinition.getParent().detachFromParent();
+        Node parent = aliasDefinition.getParent();
+        if (parent == null) {
+          // Node has already been detached, skip it.
+          continue;
+        }
+        if (parent.isVar() &&
+            parent.hasOneChild()) {
+          parent.detachFromParent();
+        } else if (parent.isFunction()) {
+          // For hoisted function declarations, remove the entire function.
+          // We check parent.isFunction() instead of isFunctionDeclaration()
+          // because the parent might not have the right structure after
+          // other transformations.
+          Node grandparent = parent.getParent();
+          if (grandparent != null) {
+            parent.detachFromParent();
+          }
         } else {
           aliasDefinition.detachFromParent();
         }
@@ -238,6 +252,40 @@ class ScopedAliases implements HotSwapCompilerPass {
     }
   }

+  private class HoistedFunctionAlias extends AliasUsage {
+    private final String scopedName;
+
+    HoistedFunctionAlias(Var aliasVar, Node aliasReference, String scopedName) {
+      super(aliasVar, aliasReference);
+      this.scopedName = scopedName;
+    }
+
+    @Override
+    public boolean referencesOtherAlias() {
+      // Hoisted functions don't reference other aliases.
+      return false;
+    }
+
+    @Override
+    public void applyAlias() {
+      // Replace the reference with a reference to the scoped name.
+      // For $jscomp.scope.name, we need to create the property access chain.
+      Node scopedRef;
+      if (scopedName.indexOf('.') == -1) {
+        // Simple name like "x"
+        scopedRef = IR.name(scopedName);
+      } else {
+        // Qualified name like "$jscomp.scope.f"
+        scopedRef = IR.name(scopedName.substring(0, scopedName.indexOf('.')));
+        for (String part : scopedName.substring(scopedName.indexOf('.') + 1).split("\\.")) {
+          scopedRef = IR.getprop(scopedRef, IR.string(part));
+        }
+      }
+      scopedRef.useSourceInfoIfMissingFromForTree(aliasReference);
+      aliasReference.getParent().replaceChild(aliasReference, scopedRef);
+    }
+  }
+

   private class Traversal implements NodeTraversal.ScopedCallback {
