     private final Map<String, Var> aliases = Maps.newHashMap();

+    // Maps hoisted function names to their scoped names (e.g., f -> $jscomp.scope.f).
+    private final Map<String, String> hoistedFunctions = Maps.newHashMap();
+
     // Suppose you create an alias.
     // var x = goog.x;
     // As a side-effect, this means you can shadow the namespace 'goog'
@@ -309,6 +360,7 @@ class ScopedAliases implements HotSwapCompilerPass {
       if (t.getScopeDepth() == 2) {
         renameNamespaceShadows(t);
         aliases.clear();
+        hoistedFunctions.clear();
         forbiddenLocals.clear();
         transformation = null;
         hasNamespaceShadows = false;
@@ -414,6 +466,52 @@ class ScopedAliases implements HotSwapCompilerPass {
                   compiler.getCodingConvention(), globalName, n, name));

           recordAlias(v);
+        } else if (parent.isFunction() && NodeUtil.isFunctionDeclaration(parent)) {
+          // Handle hoisted function declarations.
+          Node grandparent = parent.getParent();
+          Node functionNode = parent;
+
+          String name = n.getString();
+          int nameCount = scopedAliasNames.count(name);
+          scopedAliasNames.add(name);
+          String globalName =
+              "$jscomp.scope." + name + (nameCount == 0 ? "" : ("$" + nameCount));
+
+          compiler.ensureLibraryInjected("base");
+
+          // Clone the function for the assignment.
+          Node functionClone = functionNode.cloneTree();
+          // Remove the function name so it becomes an anonymous function.
+          // The function's first child is the function name.
+          // We can't just detach it, so let's set it to be empty/null.
+          Node nameNode = functionClone.getFirstChild();
+          if (nameNode != null && nameNode.isName()) {
+            // Replace the name with an empty NAME node to remove the name
+            // while keeping the function structure intact.
+            Node emptyName = IR.name("");
+            functionClone.replaceChild(nameNode, emptyName);
+          }
+
+          // Add $jscomp.scope.name = function() {...};
+          Node newDecl = NodeUtil.newQualifiedNameNodeDeclaration(
+              compiler.getCodingConvention(),
+              globalName,
+              functionClone,
+              v.getJSDocInfo())
+              .useSourceInfoIfMissingFromForTree(n);
+          NodeUtil.setDebugInformation(
+              newDecl.getFirstChild().getFirstChild(), n, name);
+
+          // Add the assignment at the beginning of the block to preserve
+          // function hoisting semantics.
+          grandparent.addChildToFront(newDecl);
+
+          // Record the function declaration node so it gets removed later.
+          aliasDefinitionsInOrder.add(n);
+
+          // Register this as an alias so references get rewritten.
+          aliases.put(name, v);
+          hoistedFunctions.put(name, globalName);
         } else {
           // Do not other kinds of local symbols, like catch params.
           report(t, n, GOOG_SCOPE_NON_ALIAS_LOCAL, n.getString());
@@ -543,13 +641,19 @@ class ScopedAliases implements HotSwapCompilerPass {
       if (t.getScopeDepth() >= 2) {
