+          // Check if this is a hoisted function alias.
+          if (hoistedFunctions.containsKey(aliasVar.getName())) {
+            String scopedName = hoistedFunctions.get(aliasVar.getName());
+            aliasUsages.add(new HoistedFunctionAlias(aliasVar, n, scopedName));
+          } else {
+            // Note, to support the transitive case, it's important we don't
